function validationPanel(backtest){const box=node("div","","validation-panel");const heading=node("div","","validation-heading");heading.append(node("strong","Out-of-sample reality check"),node("span",backtest.evidence_grade.replaceAll("_"," "),"evidence-grade "+backtest.evidence_grade.toLowerCase()));box.append(heading);for(const result of backtest.out_of_sample_results){const row=node("div","","validation-row");const name=result.setup.startsWith("UPSIDE")?"Long breakout":"Short breakdown";const expectancy=result.expectancy_r===null?"No held-out trades":Number(result.expectancy_r).toFixed(2)+"R expectancy";const winRate=result.win_rate_percent===null?"—":Number(result.win_rate_percent).toFixed(1)+"% target hits";row.append(node("span",name),node("span",result.trades+" trades · "+winRate+" · "+expectancy));box.append(row);}box.append(node("p",backtest.ranking_explanation),node("small","First 70% develops context; latest 30% is held out. Assumptions: next-bar entry · 2% stop · 4% target · 20-bar maximum · 0.10% cost. "+backtest.warning));return box;}
