function outcomeHistory(outcomes){if(!outcomes.length)return null;const box=node("section","","scan-outcomes");box.append(node("h3","What happened after earlier scans"),node("p","The arrow is raw market direction. FAVORABLE/ADVERSE judges that move against the earlier LONG or SHORT setup. This is not a fill or trading P/L."));const table=node("table","");const head=node("thead","");const hr=node("tr","");for(const label of ["Symbol / scope","Earlier assessment","Expected","From","To","Raw price move","Setup outcome","Measurement window (UTC)"])hr.append(node("th",label));head.append(hr);const body=node("tbody","");for(const item of outcomes){const tr=node("tr","");const change=Number(item.market_return_percent);const move=(change>0?"↑ ":change<0?"↓ ":"→ ")+Math.abs(change).toFixed(4)+"%";const directionWord=change>0?"rose":change<0?"fell":"was flat";const result=item.direction_result==="NOT_APPLICABLE"?"NOT APPLICABLE — no direction":item.direction_result.replaceAll("_"," ")+" — price "+directionWord+" for "+item.direction;const values=[item.symbol+" · "+item.timeframe.replaceAll("_"," ")+" · "+item.session_rule,item.readiness.replaceAll("_"," "),item.direction,"$"+item.reference_price,"$"+item.measured_price,move,result,item.assessed_at.replace("T"," ")+" → "+item.measured_at.replace("T"," ")];values.forEach((value,index)=>tr.append(node("td",value,index===6?"outcome "+item.direction_result.toLowerCase():index===5?"raw-move":"")));body.append(tr);}table.append(head,body);box.append(table);return box;}
