function blockerSummary(rows){const counts=new Map();for(const row of rows){for(const check of row.decision_checks){if(check.status==="PASS"||check.status==="INFO")continue;const item=counts.get(check.label)||{count:0,symbols:[]};item.count+=1;item.symbols.push(row.symbol);counts.set(check.label,item);}}const box=node("section","","blocker-summary");box.append(node("span","WHY NOTHING IS READY"),node("h3",counts.size?"Readiness blockers across this scan":"No blockers detected"));if(!counts.size){box.append(node("p","At least one row may be ready for the separate risk check."));return box;}const list=node("div","","blocker-list");for(const [label,item] of [...counts].sort((a,b)=>b[1].count-a[1].count||a[0].localeCompare(b[0]))){const row=node("div","");row.append(node("strong",item.count+" · "+label),node("small",item.symbols.join(", ")));list.append(row);}box.append(list,node("p","Next action: wait for new completed bars, then scan again. Do not weaken a blocker to force a plan."));return box;}
function updateOperatorChecklist(){const configured=providerReady||localImportComplete,verified=providerVerified||localImportComplete;const states=[["ready-data",configured?"done":"next"],["ready-verify",verified?"done":configured?"next":"locked"],["ready-analysis",currentAnalysis?"done":verified?"next":"locked"],["ready-plan",paperPlanEligible?"done":"locked"]];for(const [id,state] of states){const row=$(id);if(!row)continue;row.className=state;row.querySelector("em").textContent=state.toUpperCase();}}
