function detectReadinessChanges(report){const hadBaseline=lastReadiness.size>0;newReadySymbols=new Set();for(const row of report.rows){if(hadBaseline&&lastReadiness.get(row.symbol)!=="READY_FOR_RISK_CHECK"&&row.readiness==="READY_FOR_RISK_CHECK")newReadySymbols.add(row.symbol);}lastReadiness=new Map(report.rows.map(row=>[row.symbol,row.readiness]));if(monitoring&&newReadySymbols.size&&"Notification" in window&&Notification.permission==="granted"){new Notification("RevMind: new setup ready for risk check",{body:[...newReadySymbols].join(", ")+" changed to READY. Review the evidence; no order was placed."});}return [...newReadySymbols];}
