  renderNews(report);
  results.append(deskSummary(report.desk_summary),blockerSummary(report.rows),node("p",report.validation_depth.replaceAll("_"," ")+" validation · "+report.session_rule.replaceAll("_"," ")+" session · completed-bar window: "+report.requested_start.replace("T"," ")+" to "+report.requested_end.replace("T"," ")+" · source "+report.source+"."));
  const grid=node("div","","research-grid");for(const [index,row] of report.rows.entries()){const card=node("details","","research-card "+row.action.toLowerCase()+(newReadySymbols.has(row.symbol)?" new-ready":""));card.open=row.readiness==="READY_FOR_RISK_CHECK"||(row.readiness==="CAUTION"&&index<3);const summary=node("summary","","research-card-head");const title=node("div","");const rank=row.opportunity_rank===null?"": " · RANK #"+row.opportunity_rank;title.append(node("strong",row.symbol+(newReadySymbols.has(row.symbol)?" · NEWLY READY":"")),node("small",row.exchange+" · "+row.timeframe.replaceAll("_"," ")+" · "+row.evidence_grade.replaceAll("_"," ")+rank),node("span",(row.latest_close===null?"No price":"$"+row.latest_close)+" · "+(row.trend??row.trend_status.replaceAll("_"," "))+" · "+(row.active_setups.length?row.active_setups[0].replaceAll("_"," "):"NO ENTRY"),"research-glance"));summary.append(title,node("span",row.readiness.replaceAll("_"," "),"decision-pill "+row.readiness.toLowerCase()));card.append(summary);const detail=node("div","","research-detail");detail.append(sparkline(row.chart));
    const facts=node("div","","research-facts");for(const [label,value] of [["Latest close",row.latest_close??"—"],["Trend",row.trend??row.trend_status.replaceAll("_"," ")],["Setup",row.active_setups.length?row.active_setups.join(", ").replaceAll("_"," "):"None active"],["Bars analyzed",String(row.bar_count)]]){const fact=node("div","");fact.append(node("small",label),node("strong",value));facts.append(fact);}const notes=node("div","","opportunity-notes");for(const [label,value] of [["Trend",row.trend_comment],["What RevMind sees",row.opportunity_comment],["Where",row.price_location],["Broad market",row.market_comment],["Relative strength",row.relative_strength_comment],["Recent catalysts",row.catalyst_comment],["Evidence",row.evidence_comment],["What to do",row.next_step]]){const note=node("p","");note.append(node("strong",label+": "),document.createTextNode(value));notes.append(note);}if(row.recent_news?.length){const news=node("div","","recent-news");for(const item of row.recent_news){const link=node("a",item.headline);link.href=item.url;link.target="_blank";link.rel="noopener noreferrer";const entry=node("p","");entry.append(link,node("small",item.published_at.replace("T"," ")+" · "+item.source));news.append(entry);}notes.append(news);}detail.append(facts,readinessPanel(row),notes,validationPanel(row.backtest));if(row.latest_bar_at)detail.append(node("small","Latest completed bar: "+row.latest_bar_at.replace("T"," "),"research-time"));if(row.readiness==="READY_FOR_RISK_CHECK"&&row.assessment_id){const button=node("button","Review automatic plan","secondary plan-button");button.type="button";button.onclick=()=>openPaperPlan(row,true);detail.append(button);}card.append(detail);grid.append(card);}results.append(grid);const technical=node("details","","technical-results");technical.append(node("summary","Show technical validation and past measurements"),calibrationPanel(report.calibration));const history=outcomeHistory(report.recent_outcomes);if(history)technical.ap