function paperPlanPayload(){return {assessment_id:$("assessment-id").value,side:$("paper-side").value,quantity:$("paper-quantity").value,cash_balance:$("paper-cash").value,auto_size:true,max_trade_notional:$("paper-max-trade").value,max_gross_exposure:$("paper-max-gross").value,max_instrument_exposure:$("paper-max-instrument").value,max_concentration_share:$("paper-max-share").value,min_cash_balance:$("paper-min-cash").value,stop_price:$("paper-stop").value,max_loss_budget:$("paper-max-loss").value};}
async function calculatePaperPlan(){const plan=await api("/api/paper-plan","POST",paperPlanPayload());paperPlanEligible=plan.status==="ELIGIBLE_FOR_PAPER_REVIEW";updateOperatorChecklist();showPaperPlan(plan);return plan;}
async function openPaperPlan(row,scroll=true){$("assessment-id").value=row.assessment_id;$("paper-title").textContent="RevMind plan for "+row.symbol;$("paper-side").value=row.active_setups.includes("DOWNSIDE_BREAKDOWN_BELOW_SMA")?"SELL":"BUY";$("paper-stop").value=row.suggested_stop??"";$("paper-cash").value="0";$("check-paper").disabled=true;$("paper-result").className="paper-result";$("paper-result").replaceChildren(node("p",row.stop_comment),node("small","RevMind is synchronizing paper capacity, sizing the position, and applying every risk veto…"));$("paper-planner").hidden=false;if(scroll)$("paper-planner").scrollIntoView({behavior:"smooth",block:"start"});notice("Building the complete risk-bounded plan automatically…");try{const account=await syncPaperAccount(false);if(account.trading_blocked)throw new Error("Alpaca reports that paper trading is blocked.");$("check-paper").disabled=false;const plan=await calculatePaperPlan();notice(plan.status==="ELIGIBLE_FOR_PAPER_REVIEW"?"RevMind generated a complete paper-trade plan. Review it; nothing was submitted.":"RevMind generated the plan and the safety layer blocked it. No order was submitted.");return plan;}catch(e){$("paper-result").append(node("p","Automatic plan generation failed: "+e.message,"danger"));notice(e.message);return null;}}
async function autoBuildLeadPlan(report){const lead=report.rows.find(row=>row.symbol===report.desk_summary.lead_symbol&&row.readiness==="READY_FOR_RISK_CHECK"&&row.assessment_id);if(!lead){$("paper-planner").hidden=true;return null;}return openPaperPlan(lead,false);}
function showPaperPlan(plan){$("paper-quantity").value=plan.quantity;const box=$("paper-result");box.className="paper-result "+plan.status.toLowerCase();box.replaceChildren();box.append(node("h3",plan.status.replaceAll("_"," ")),node("p",plan.explanation));if(plan.sizing_basis.length){const sizing=node("div","","opportunity-notes");sizing.append(node("strong","Why this size"));for(const line of plan.sizing_basis)sizing.append(node("p",line));box.append(sizing);}const grid=node("div","","paper-result-grid");for(const [label,value] of [["Paper trade",plan.side+" "+plan.quantity+" "+plan.symbol],["Entry limit","$"+plan.reference_price],["Protective stop","$"+plan.stop_price],["Illustrative 2R target","$"+plan.target_price],["Maximum loss","$"+plan.estimated_loss_at_stop],["Cash after entry",plan.projected_cash===null?"Unavailable":"$"+plan.projected_cash]]){const fact=node("div","");fact.append(node("small",label),node("strong",value));grid.append(fact);}box.append(grid,node("strong","Risk: "+plan.risk_status.replaceAll("_"," ")+" · Desk: "+plan.desk_disposition.replaceAll("_"," ")));const reasons=[...plan.risk_reasons,...plan.desk_reasons];box.append(node("code",reasons.length?"Reasons: "+reasons.join(", ").replaceAll("_"," "):"No blocking reasons."));if(plan.approval_id){const approve=node("button","Approve Alpaca paper order","approve-paper");approve.type="button";approve.onclick=()=>placePaperOrder(plan,approve);box.append(approve,node("small","This submits a limit bracket order to Alpaca Paper Trading only.","approval-help"));}}
async function placePaperOrder(plan,button){if(!window.confirm("Submit this bracket order to Alpaca PAPER Trading? No real money will be used."))return;button.disabled=true;notice("Submitting the explicitly approved order to Alpaca Paper Trading…");try{const receipt=await api("/api/paper-order","POST",{approval_id:plan.approval_id,confirmation:"PLACE PAPER ORDER"});const box=$("paper-result");box.append(node("h3","PAPER ORDER SUBMITTED"),node("p",receipt.side.toUpperCase()+" "+receipt.quantity+" "+receipt.symbol+" · "+receipt.status.replaceAll("_"," ")+" · "+receipt.provider_order_id));notice("Alpaca Paper Trading accepted the order. Sync the paper account to review its state.");button.remove();await loadPaperOrders();}catch(e){notice(e.message);button.disabled=false;}}
$('paper-form').onsubmit=async e=>{e.preventDefault();$("check-paper").disabled=true;notice("Recalculating the complete plan with your updated risk limits…");try{await calculatePaperPlan();notice("Plan recalculated. RevMind did not submit an order.");}catch(e){notice(e.message);}finally{$("check-paper").disabled=false;}};
