function allBarsStale(report){return Boolean(report?.rows.length)&&report.rows.every(row=>row.decision_checks.some(check=>check.label==="Bar freshness"&&check.status==="BLOCK"));}
async function runMarketScan(){if(scanRunning||!providerReady)return;scanRunning=true;currentAnalysis=false;paperPlanEligible=false;updateOperatorChecklist();$("run-market").disabled=true;const started=Date.now();$("research-status").textContent="CHECKING · 0s";scanTimer=setInterval(()=>$("research-status").textContent="CHECKING · "+Math.floor((Date.now()-started)/1000)+"s",1000);notice("Checking your watchlist and preparing a plan when the evidence qualifies…");try{const report=await api("/api/alpaca/research","POST");currentAnalysis=true;updateOperatorChecklist();const changed=detectReadinessChanges(report);showResearch(report);const ready=report.desk_summary.ready_count;if(ready){const plan=await autoBuildLeadPlan(report);if(!plan)notice("A setup qualified, but RevMind could not complete its risk plan. Nothing was submitted.");}else notice(changed.length?changed.join(", ")+" changed state, but no setup passed the full plan gate.":report.desk_summary.headline);if(monitoring&&allBarsStale(report)){stopMonitoring("Paused · market bars are stale");notice("Monitoring paused: every instrument has stale completed bars. Start it again when the selected market is open.");}}catch(e){$("research-status").textContent="FAILED SAFELY";notice(e.message);}finally{if(scanTimer!==null)clearInterval(scanTimer);scanTimer=null;scanRunning=false;$("run-market").disabled=!providerReady;}}
async function restoreLatestResearch(){try{const report=await api("/api/alpaca/research/latest");if(!report)return;showResearch(report);$("research-status").textContent="LAST SAVED · "+report.feed;const reminder=node("p","Saved result from "+report.completed_at.replace("T"," ")+". Re-scan before generating any current plan.","saved-research-note");$("research-results").prepend(reminder);}catch(e){console.warn("Latest saved research could not be restored.",e);}}
function monitorDelay(){const minutes={ONE_MINUTE:5,FIVE_MINUTES:15,FIFTEEN_MINUTES:15,ONE_HOUR:60,ONE_DAY:60}[$("timeframe").value]??15;return minutes*60000;}
function stopMonitoring(status="Monitoring off · nothing trades without approval"){monitoring=false;if(monitorTimer!==null)clearTimeout(monitorTimer);monitorTimer=null;$("auto-scan").textContent="Start monitoring";$("auto-scan-status").textContent=status;}
async function monitorTick(){if(!monitoring)return;if(!providerReady){stopMonitoring();notice("Monitoring stopped because Alpaca is not ready.");return;}await runMarketScan();if(!monitoring)return;const minutes=monitorDelay()/60000;$("auto-scan-status").textContent="Monitoring every "+minutes+" min while this page is open · no automatic orders";monitorTimer=setTimeout(monitorTick,monitorDelay());}
