async function loadPaperOrders(){const orders=await api("/api/paper-orders");document.querySelector(".paper-order-history")?.remove();if(!orders.length)return;const result=$("paper-account-result");const history=node("div","","paper-order-history");history.append(node("strong","Recent RevMind paper orders"));const active=new Set(["ACCEPTED","NEW","PENDING_NEW","PARTIALLY_FILLED","HELD","CALCULATED"]);for(const order of orders.slice(0,5)){const item=node("div","","order-status-item");item.append(node("p",order.side.toUpperCase()+" "+order.quantity+" "+order.symbol+" · "+order.status.replaceAll("_"," ")+(order.submitted_at?" · "+order.submitted_at:"")));const bracket=node("div","","order-bracket");for(const [label,value] of [["Entry","$"+order.entry_limit],["Stop","$"+order.stop_price],["2R target","$"+order.target_price],["Planned loss","$"+order.planned_loss]]){const fact=node("span","");fact.append(node("small",label),node("strong",value));bracket.append(fact);}item.append(bracket,node("small",order.protection_note),node("small",order.next_action));if(active.has(order.status.toUpperCase())){const cancel=node("button","Cancel paper order","secondary compact-action");cancel.type="button";cancel.onclick=()=>cancelPaperOrder(order,cancel);item.append(cancel);}history.append(item);}result.append(history);}
