function renderPositions(result,positions){if(!positions.length){result.append(node("p","No open paper positions."));return;}const heading=node("div","","position-heading");heading.append(node("strong","Open paper positions"),node("small","Red minus = current unrealized paper loss since entry. Green plus = current unrealized paper gain."));result.append(heading);const table=node("table","","position-table");const head=node("thead","");const header=node("tr","");for(const label of ["Symbol","Shares","Avg entry","Current","Market value","Unrealized paper P/L","Review"]){header.append(node("th",label));}head.append(header);const body=node("tbody","");for(const position of positions){const row=node("tr","");const percent=(Number(position.unrealized_profit_loss_percent)*100).toFixed(2)+"%";const profit=Number(position.unrealized_profit_loss);const cue=profit>0?"Protect gains; verify stop.":profit<0?"Check thesis and stop.":"Monitor against the plan.";const values=[position.symbol,position.quantity,"$"+position.average_entry_price,"$"+position.current_price,"$"+position.market_value,(profit>=0?"+":"")+"$"+position.unrealized_profit_loss+" ("+percent+")",cue];values.forEach((value,index)=>row.append(node("td",value,index===5?(profit>=0?"positive":"danger"):"")));body.append(row);}table.append(head,body);result.append(table);}
